import{_ as t,o as d,c as i,a2 as o}from"./chunks/framework.CqGPl1zp.js";const a="data:image/svg+xml;base64,",c="/newx-doc/assets/%E6%98%8E%E7%BB%86%E8%B4%A6.DKSY5Ny-.png",s="/newx-doc/assets/%E6%80%BB%E8%B4%A6.9hRrVuEg.png",l="/newx-doc/assets/%E7%A7%91%E7%9B%AE%E4%BD%99%E9%A2%9D%E8%A1%A8.Dl1itAnI.png",r="/newx-doc/assets/%E5%A4%9A%E6%A0%8F%E8%B4%A6.Cty_VcuA.png",I="/newx-doc/assets/%E6%A0%B8%E7%AE%97%E9%A1%B9%E7%9B%AE%E6%98%8E%E7%BB%86%E8%B4%A6.DIBo8z4r.png",n="/newx-doc/assets/%E6%A0%B8%E7%AE%97%E9%A1%B9%E7%9B%AE%E4%BD%99%E9%A2%9D%E8%A1%A8.BG6VDrl5.png",g="/newx-doc/assets/%E6%95%B0%E9%87%8F%E9%87%91%E9%A2%9D%E6%98%8E%E7%BB%86%E8%B4%A6.CeVeqMGl.png",m="/newx-doc/assets/%E6%95%B0%E9%87%8F%E9%87%91%E9%A2%9D%E6%80%BB%E8%B4%A6.C6e-JrWd.png",h="/newx-doc/assets/%E8%B4%A6%E7%B0%BF%E6%89%93%E5%8D%B0%E9%A2%84%E8%A7%88.BR9D1nYs.png",E=JSON.parse('{"title":"【账簿】账簿管理","description":"","frontmatter":{},"headers":[],"relativePath":"fms/ledger.md","filePath":"fms/ledger.md","lastUpdated":null}'),p={name:"fms/ledger.md"};function b(u,e,j,P,Z,B){return d(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="【账簿】账簿管理" tabindex="-1">【账簿】账簿管理 <a class="header-anchor" href="#【账簿】账簿管理" aria-label="Permalink to &quot;【账簿】账簿管理&quot;">​</a></h1><p>账簿管理模块，由 <code>yudao-module-fms</code> 后端模块的 <code>ledger</code> 包实现，前端实现在 <code>@/views/fms/ledger</code> 目录。</p><p>账簿是对当前账套<strong>初始余额和凭证分录的实时查询结果</strong>，不单独保存账簿业务表。明细账、总账、科目余额表、多栏账、核算项目账和数量金额账共八张账簿，共用同一套取数逻辑和会计期间。</p><ul><li><strong>取数来源</strong>：期初余额来自 <code>fms_initial_balance</code>，发生额来自 <code>fms_voucher</code> 和 <code>fms_voucher_entry</code>，科目与辅助核算来自设置管理。</li><li><strong>查询方式</strong>：八类账簿都由 FmsLedgerController 提供接口（<code>/fms/ledger</code>），FmsLedgerService 按账套、期间、科目和辅助项目实时计算。</li><li><strong>页面能力</strong>：查询结果支持 Excel 导出和浏览器打印；明细账、总账、科目余额表和多栏账支持按凭证字号或科目编码钻取。</li></ul><p>本文涉及表如下图所示：</p><p><img src="'+a+'" alt="账簿表关系"></p><h2 id="_1-取数来源" tabindex="-1">1. 取数来源 <a class="header-anchor" href="#_1-取数来源" aria-label="Permalink to &quot;1. 取数来源&quot;">​</a></h2><p>账簿<strong>没有独立的 <code>fms_ledger</code> 表</strong>，涉及的数据表如下：</p><table tabindex="0"><thead><tr><th>表</th><th>关系与用途</th></tr></thead><tbody><tr><td><code>fms_initial_balance</code></td><td>按账套和科目保存期初金额、数量、本年累计和辅助余额，提供账簿的期初数</td></tr><tr><td><code>fms_voucher</code></td><td>保存凭证日期、凭证字号、凭证期间、借贷合计和审核状态</td></tr><tr><td><code>fms_voucher_entry</code></td><td>通过 <code>voucher_id</code> 关联凭证，保存摘要、科目、借贷金额、数量、单价及辅助项目</td></tr><tr><td><code>fms_subject</code></td><td>保存科目树、余额方向、层级和数量核算标识</td></tr><tr><td><code>fms_assist_combination</code></td><td>保存账套下科目与辅助项目的组合，核算项目账按它聚合</td></tr></tbody></table><p>① 完整建表语句见 <a href="./config/accounting">《【设置】币别、科目、辅助核算、初始余额》</a> 和 <a href="./voucher">《【凭证】凭证管理》</a>，本篇不重复展开。</p><p>② 分录同时保留 <code>subject_id</code>、<code>subject_code</code> 和 <code>subject_name</code>。<strong>账簿按 <code>subject_id</code> 关联现行科目读取编码和名称</strong>，分录中的编码、名称快照主要用于凭证自身展示。</p><p>③ 账簿余额列的显示口径由财务参数的 <code>ledger_balance_mode</code> 决定，枚举 <code>FmsLedgerBalanceModeEnum</code>：</p><table tabindex="0"><thead><tr><th>值</th><th>枚举</th><th>说明</th></tr></thead><tbody><tr><td><code>1</code></td><td><code>SAME_AS_SUBJECT</code></td><td>与科目方向相同</td></tr><tr><td><code>2</code></td><td><code>OPPOSITE_TO_SUBJECT</code></td><td>与科目方向相反</td></tr></tbody></table><p>余额方向本身由枚举 <code>FmsBalanceDirectionEnum</code> 表示：借、贷、平（余额为 0 时显示「平」）。</p><h2 id="_2-管理后台" tabindex="-1">2. 管理后台 <a class="header-anchor" href="#_2-管理后台" aria-label="Permalink to &quot;2. 管理后台&quot;">​</a></h2><p>对应 [财务管理 -&gt; 账簿管理] 菜单，对应 <code>yudao-ui-admin-vue3</code> 项目的 <code>@/views/fms/ledger</code> 目录。八张账簿共用 <code>FmsLedgerSearchBar.vue</code> 查询条、<code>FmsLedgerMonthRangePicker.vue</code> 期间选择器和 <code>FmsLedgerPrintButton.vue</code> 打印按钮。</p><h3 id="_2-1-明细账" tabindex="-1">2.1 明细账 <a class="header-anchor" href="#_2-1-明细账" aria-label="Permalink to &quot;2.1 明细账&quot;">​</a></h3><p>对应 [财务管理 -&gt; 账簿管理 -&gt; 明细账] 菜单，对应 <code>@/views/fms/ledger/detail</code> 目录。页面先由 <code>getDetailSubjectList</code> 加载<strong>期间内有发生额的科目</strong>，再由 <code>getDetailList</code> 查询该科目的逐笔明细。点击凭证字号跳转到录凭证页面查看原始凭证。</p><p><img src="'+c+'" alt="管理后台 - 明细账"></p><h3 id="_2-2-总账" tabindex="-1">2.2 总账 <a class="header-anchor" href="#_2-2-总账" aria-label="Permalink to &quot;2.2 总账&quot;">​</a></h3><p>对应 [财务管理 -&gt; 账簿管理 -&gt; 总账] 菜单，对应 <code>@/views/fms/ledger/general</code> 目录。<code>getGeneralList</code> 按科目和期间汇总期初、本期发生额和期末余额，点击科目编码进入明细账。</p><p><img src="'+s+'" alt="管理后台 - 总账"></p><h3 id="_2-3-科目余额表" tabindex="-1">2.3 科目余额表 <a class="header-anchor" href="#_2-3-科目余额表" aria-label="Permalink to &quot;2.3 科目余额表&quot;">​</a></h3><p>对应 [财务管理 -&gt; 账簿管理 -&gt; 科目余额表] 菜单，对应 <code>@/views/fms/ledger/subject-balance</code> 目录。<code>getSubjectBalanceList</code> 返回<strong>树形结果</strong>，页面按科目树展示各级余额，点击科目进入明细账；导出时后端会先把树展平。</p><p><img src="'+l+'" alt="管理后台 - 科目余额表"></p><h3 id="_2-4-多栏账" tabindex="-1">2.4 多栏账 <a class="header-anchor" href="#_2-4-多栏账" aria-label="Permalink to &quot;2.4 多栏账&quot;">​</a></h3><p>对应 [财务管理 -&gt; 账簿管理 -&gt; 多栏账] 菜单，对应 <code>@/views/fms/ledger/multi-column</code> 目录。<code>getMultiColumn</code> 返回<strong>动态科目列和账簿行</strong>，把下级科目横向展开成栏；凭证字号同样可以钻取，导出使用动态表头。</p><p><img src="'+r+'" alt="管理后台 - 多栏账"></p><h3 id="_2-5-核算项目明细账" tabindex="-1">2.5 核算项目明细账 <a class="header-anchor" href="#_2-5-核算项目明细账" aria-label="Permalink to &quot;2.5 核算项目明细账&quot;">​</a></h3><p>对应 [财务管理 -&gt; 账簿管理 -&gt; 核算项目明细账] 菜单，对应 <code>@/views/fms/ledger/auxiliary-detail</code> 目录。页面使用 <code>FmsAuxiliaryTypeSelect.vue</code> 和 <code>FmsAuxiliaryItemSelect.vue</code> 选择辅助类别与项目，<code>getAuxiliaryDetailList</code> 按辅助项目、科目和期间查询逐笔明细。</p><p><img src="'+I+'" alt="管理后台 - 核算项目明细账"></p><h3 id="_2-6-核算项目余额表" tabindex="-1">2.6 核算项目余额表 <a class="header-anchor" href="#_2-6-核算项目余额表" aria-label="Permalink to &quot;2.6 核算项目余额表&quot;">​</a></h3><p>对应 [财务管理 -&gt; 账簿管理 -&gt; 核算项目余额表] 菜单，对应 <code>@/views/fms/ledger/auxiliary-balance</code> 目录。<code>getAuxiliaryBalanceList</code> 按辅助项目汇总期初、发生额和期末余额，用于核对某个客户、供应商或项目的往来余额。</p><p><img src="'+n+'" alt="管理后台 - 核算项目余额表"></p><h3 id="_2-7-数量金额明细账" tabindex="-1">2.7 数量金额明细账 <a class="header-anchor" href="#_2-7-数量金额明细账" aria-label="Permalink to &quot;2.7 数量金额明细账&quot;">​</a></h3><p>对应 [财务管理 -&gt; 账簿管理 -&gt; 数量金额明细账] 菜单，对应 <code>@/views/fms/ledger/quantity-detail</code> 目录。<code>getQuantityDetailList</code> 在明细账基础上增加数量、单价列。<strong>只有启用数量核算的科目才有数量和单价</strong>。</p><p><img src="'+g+'" alt="管理后台 - 数量金额明细账"></p><h3 id="_2-8-数量金额总账" tabindex="-1">2.8 数量金额总账 <a class="header-anchor" href="#_2-8-数量金额总账" aria-label="Permalink to &quot;2.8 数量金额总账&quot;">​</a></h3><p>对应 [财务管理 -&gt; 账簿管理 -&gt; 数量金额总账] 菜单，对应 <code>@/views/fms/ledger/quantity-general</code> 目录。<code>getQuantityGeneralList</code> 按科目树汇总数量和金额，导出时同样展平科目树。</p><p><img src="'+m+'" alt="管理后台 - 数量金额总账"></p><h3 id="_2-9-打印" tabindex="-1">2.9 打印 <a class="header-anchor" href="#_2-9-打印" aria-label="Permalink to &quot;2.9 打印&quot;">​</a></h3><p>八张账簿的打印都由 <code>FmsLedgerPrintButton.vue</code> 打开 <code>FmsPrintPreview.vue</code>，在浏览器端渲染当前表格，<strong>不调用后端打印接口</strong>。</p><p><img src="'+h+'" alt="管理后台 - 明细账打印入口"></p><p>查询说明</p><p>账套未初始化或没有当前账套时，页面不发起查询。会计期间由 <code>FmsLedgerMonthRangePicker.vue</code> 选择，点击【重置】会回到账套的当前会计期间。</p><p>账簿是<strong>只读</strong>的，不提供新增、修改和删除；数据不对时应回到凭证或初始余额修正，账簿会在下一次查询时立即反映。</p>',46)])])}const N=t(p,[["render",b]]);export{E as __pageData,N as default};
